    TierValue = apps.get_model("habits", "TierValue")
    Tier = apps.get_model("habits", "Tier")
    HabitLog = apps.get_model("habits", "HabitLog")
    Schedule = apps.get_model("habits", "Schedule")
    ScheduleDay = apps.get_model("habits", "ScheduleDay")
    Version = apps.get_model("habits", "Version")

    tier_level = {t.id: t.level for t in Tier.objects.all()}

